const {JSDOM}=require('jsdom');const fs=require('fs');
const html=fs.readFileSync((process.env.APP||require('path').join(__dirname,'..','taskspeck-managers.html')),'utf8');
const errs=[];
const dom=new JSDOM(html,{runScripts:'dangerously',pretendToBeVisual:true,url:'https://example.org/?demo=1',beforeParse(w){w.addEventListener('error',e=>errs.push(e.message))}});
const w=dom.window,d=w.document;let fail=0;
const ok=(c,m)=>{if(!c){fail++;console.log('FAIL',m)}else console.log('ok  ',m)};
const $=s=>d.querySelector(s),$$=s=>[...d.querySelectorAll(s)],ev=c=>w.eval(c),txt=()=>$('#view').textContent;
const click=s=>{const e=typeof s==='string'?$(s):s;if(!e)throw new Error('missing '+s);e.click()};
const type=(s,v)=>{const e=$(s);e.value=v;e.dispatchEvent(new w.Event('input',{bubbles:true}));e.dispatchEvent(new w.Event('change',{bubbles:true}))};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const addFile=async(file)=>{const el=$('[data-nbimg]');Object.defineProperty(el,'files',{value:[file],configurable:true});el.dispatchEvent(new w.Event('change',{bubbles:true}));await sleep(150)};
(async()=>{try{
 await sleep(300);
 ev("S.prof.role='Building manager';S.prof.pay='bank';S.prof.consent=true;S.stack=[];S.tab.manager='bld';render()");
 click('[data-a=bnew]');
 ok($('#addb').classList.contains('open')&&$('[data-nbimg]')&&/Building photos \(optional\)/.test($('#addb').textContent)&&/No photos yet/.test($('#addb').textContent),'the Add a building form has a photo upload');
 type('[data-m="nb.name"]','Balwyn Court');type('[data-m="nb.street"]','2 Sample Road');const sb=$('input[data-m=\"nb.suburb\"]');sb.value='Balwyn';sb.dispatchEvent(new w.Event('input',{bubbles:true}));{const pe=$('input[data-m="nb.pc"]');pe.value='3103';pe.dispatchEvent(new w.Event('input',{bubbles:true}))};type('[data-m="nb.oc"]','PS 777');
 await addFile(new w.File(['AAA'],'front.png',{type:'image/png'}));
 ok(ev('S.nb.imgs.length')===1&&$$('#addb img[alt^="New building photo"]').length===1&&/Photo added/.test($('#toast').textContent),'a photo can be added while adding a building');
 ok($('[data-m="nb.name"]').value==='Balwyn Court'&&$('[data-m="nb.street"]').value==='2 Sample Road'&&$('input[data-m="nb.suburb"]').value==='Balwyn'&&$('[data-m="nb.oc"]').value==='PS 777'&&$('#addb').classList.contains('open'),'the details already typed are kept when a photo is added');
 await addFile(new w.File(['TXT'],'a.txt',{type:'text/plain'}));ok(/Choose an image file/.test($('#toast').textContent)&&ev('S.nb.imgs.length')===1,'a file that is not an image is refused');
 await addFile(new w.File([new Uint8Array(3*1024*1024+10)],'big.jpg',{type:'image/jpeg'}));ok(/over 3 MB/.test($('#toast').textContent)&&ev('S.nb.imgs.length')===1,'a photo over 3 MB is refused');
 await addFile(new w.File(['BBB'],'lobby.jpg',{type:'image/jpeg'}));
 ok(ev('S.nb.imgs.length')===2&&!$('[data-nbimg]'),'a second photo can be added and then the button goes');
 click('[data-a=nbimgdel][data-v="0"]');ok(ev('S.nb.imgs.length')===1&&$('[data-nbimg]'),'a photo can be removed before saving');
 await addFile(new w.File(['CCC'],'side.png',{type:'image/png'}));
 click('[data-a=bsave]');
 const nb=ev("B[B.length-1]");ok(ev("B.length")===4&&nb.name==='Balwyn Court'&&nb.imgs.length===2&&ev("S.nb.name===''&&S.nb.imgs.length===0"),'saving creates the building with its two photos');
 ok(/2 of 2 photos/.test($('.bsec[data-k="b4:photos"] .bsec-h').textContent)&&$$('.bcard[data-b=b4] img[alt^="Building photo"]').length===2,'the new building shows its photos in the Building photos group');
 ev("J.find(j=>j.id==='m1').bid='b4';S.stack=[];S.role='contractor';S.tab.contractor='find';render();go('cjob',{id:'m1'})");
 ok(/The building/.test(txt())&&$$('#view img[alt^="Building photo"]').length===2,'contractors see the photos on jobs for the new building');
 // an address outside the area keeps nothing
 ev("S.stack=[];S.role='manager';S.tab.manager='bld';S.bopen={b:null,s:{},add:false};render()");click('[data-a=bnew]');
 ev("S.set.radius=12");type('[data-m="nb.name"]','Box Hill Towers');type('[data-m="nb.street"]','1 Sample Street');const s2=$('input[data-m=\"nb.suburb\"]');s2.value='Box Hill';s2.dispatchEvent(new w.Event('input',{bubbles:true}));{const pe=$('input[data-m="nb.pc"]');pe.value='3128';pe.dispatchEvent(new w.Event('input',{bubbles:true}))};
 await addFile(new w.File(['DDD'],'x.png',{type:'image/png'}));click('[data-a=bsave]');
 ok(/We do not cover this area yet/.test($('#addb').textContent)&&ev("B.length")===4,'an address outside the area is not saved, even with a photo');
 click('[data-a=wait]');ok(ev("S.nb.name===''&&S.nb.imgs.length===0")&&ev('B.length')===4,'joining the waiting list clears the form');
 console.log(errs.length?'ERRORS '+errs.join('|'):'no script errors');console.log(fail?fail+' FAILED':'ALL PASSED');
}catch(e){console.log('EXCEPTION',e.message,'\n',e.stack.split('\n').slice(0,4).join('\n'))}process.exit(0)})();
